"use client";
import type{ReactNode}from"react";import Link from"next/link";import{AuthGate}from"./auth-gate";import{usePlayerData}from"../../lib/use-player-data";import{getSupabaseBrowserClient}from"../../lib/supabase/client";
const nav=[["today","Today","/"],["rounds","Rounds","/rounds/new"],["performance","Performance","/performance"],["diagnostics","Evidence","/diagnostics"],["programme","Programme","/programme"],["practice","Practice","/practice"],["progress","Progress","/progress"],["sessions","Sessions","/sessions"],["coach","Coach","/coach"],["players","Players","/players"],["trackman","TrackMan","/trackman"],["library","Library","/library"],["pilot","Pilot","/pilot"],["release","Release","/release"],["settings","Settings","/settings"]]as const;
export function AppShell({active,children}:{active:string;children:ReactNode}){const{profile}=usePlayerData();const name=profile?.display_name||profile?.email||"Selected player";const initials=name.split(/\s|@/).filter(Boolean).slice(0,2).map(part=>part[0]).join("").toUpperCase();const coach=profile?.role==="coach"||profile?.role==="admin";const visibleNav=nav.filter(([id])=>coach?id!=="rounds":!["coach","sessions","players","library","release"].includes(id));const signOut=async()=>{await getSupabaseBrowserClient()?.auth.signOut();window.location.replace("/auth/login")};return <AuthGate><div className="app-frame"><a className="skip-link" href="#main-content">Skip to main content</a><header className="topbar"><Link className="brand" href="/" aria-label="Vector Golf Performance home"><span className="brand-mark" aria-hidden="true">V</span><span>VECTOR <small>GOLF PERFORMANCE</small></span></Link><nav aria-label="Primary navigation">{visibleNav.map(([id,label,href])=><Link aria-current={active===id?"page":undefined} className={active===id?"active":""} href={href} key={id}>{label}</Link>)}</nav><button className="profile profile-button" onClick={signOut} title="Sign out"><span><strong>{name}</strong><small>{profile?.role||"Beta access"} · Sign out</small></span><b aria-hidden="true">{initials||"VG"}</b></button></header><main id="main-content" tabIndex={-1} className="main-content">{children}</main><nav className="mobile-nav" aria-label="Mobile navigation">{visibleNav.map(([id,label,href])=><Link aria-current={active===id?"page":undefined} className={active===id?"active":""} href={href} key={id}><span aria-hidden="true">{id==="today"?"⌂":id==="rounds"?"+":id==="performance"?"↗":id==="diagnostics"?"◎":id==="programme"?"▦":id==="practice"?"✓":id==="progress"?"↻":id==="coach"?"◉":"◇"}</span>{label}</Link>)}</nav></div></AuthGate>}
